mapper.sql:
SELECT lbd.id as detailId, lb.id as id, lb.sales_platform AS salesPlatform, lb.shop_id AS shopId, lb.shop_name AS shopName, lb.source_type AS sourceType, lb.order_type AS orderType, lb.source_id AS sourceId, lb.source_code AS sourceCode, lb.outstock_id AS outstockId, lb.outstock_code AS outstockCode, lb.channel_id AS channelId, lb.order_time AS orderTime, lb.delivery_time AS deliveryTime, lb.transport_no AS transportNo, lb.to_country AS toCountry, lbd.track_status AS trackStatus , lbd.track_no AS trackNo, lbd.sign_time AS signTime, lbd.track_query_mode AS trackQueryMode, lc.name AS channelName, lc.track_query_type AS trackQueryType, lb.platform_code as platformCode, lb.shipment_type as shipmentType FROM logistics_bill lb LEFT JOIN logistics_bill_detail lbd ON lbd.main_id=lb.id and (lbd.is_deleted=false or lbd.is_deleted is null) LEFT JOIN logistics_channel lc ON lc.id=lb.channel_id and lc.is_deleted=false
${params.sqlMap.default} and lb.is_deleted=false and lb.order_type in ('B2B','B2C')
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
lb.create_time DESC

mapper.select:
SELECT lb.shop_id, lb.shop_name, lb.source_type, lb.source_id, lb.source_code, lb.transport_no, lbd.track_status, lbd.track_no FROM logistics_bill lb LEFT JOIN logistics_bill_detail lbd ON lb.id = lbd.main_id AND lbd.is_deleted = FALSE WHERE lb.is_deleted = FALSE
AND lb.source_id IN
#{sourceId}

SELECT lb.id, lb.shop_id, lb.shop_name, lb.source_type, lb.source_id, lb.source_code, lb.outstock_id, lb.outstock_code, lb.transport_no, lbd.id as detailId, lbd.track_status, lbd.track_no FROM logistics_bill lb LEFT JOIN logistics_bill_detail lbd ON lb.id = lbd.main_id AND lbd.is_deleted = FALSE WHERE lb.is_deleted = FALSE
AND lbd.track_no IN
#{trackNo}

SELECT COUNT(1) AS count, lbd.track_status AS tabFlag FROM logistics_bill lb LEFT JOIN logistics_bill_detail lbd ON lbd.main_id=lb.id and (lbd.is_deleted=false or lbd.is_deleted is null) LEFT JOIN logistics_channel lc ON lc.id=lb.channel_id and lc.is_deleted=false WHERE lb.is_deleted=false and lb.order_type in ('B2B','B2C')
${permissionSql}
GROUP BY track_status

SELECT DISTINCT lbd.id AS detailId, lb.id, lb.sales_platform AS salesPlatform, lb.shop_id AS shopId, lb.shop_name AS shopName, lb.source_type AS sourceType, lb.order_type AS orderType, lb.source_id AS sourceId, lb.source_code AS sourceCode, lb.outstock_id AS outstockId, lb.outstock_code AS outstockCode, lb.channel_id AS channelId, lb.order_time AS orderTime, lb.delivery_time AS deliveryTime, lb.transport_no AS transportNo, lb.to_country AS toCountry, lbd.track_no AS trackNo FROM logistics_bill_detail lbd LEFT JOIN logistics_bill lb ON lbd.main_id=lb.id ANd lb.is_deleted = false WHERE lbd.is_deleted = false
AND lb.transport_no IN
#{transportNo}

with tms_cost as ( select lbc.logistics_bill_id, SUM(CASE WHEN tcd.TYPE = 'estimated' THEN tcd.cost_value ELSE 0 END) AS estimatedFee, SUM(CASE WHEN tcd.TYPE = 'actual' THEN tcd.cost_value ELSE 0 END) AS actualFee from tms_cost_detail tcd inner join logistics_bill_cost lbc on lbc.id = tcd.main_id where tcd.is_deleted = false and lbc.is_deleted = false GROUP BY lbc.logistics_bill_id ), tms_logistics as ( SELECT lb.id, lb.shop_id as shopId, lb.outstock_id as outstockId, lb.transport_no as transportNo, lb.counter_no as counterNo, lb.carrier_id as carrierId, lb.outstock_code as outstockCode, lb.business_code as businessCode, lbd.id as detailId, lbd.track_no as trackNo, lbd.track_status as logisticsStatus, lbd.track_content as logisticsTrack , lb.invoices_status as invoicesStatus, lb.shipping_method as shippingMethod, lb.channel_id as logisticsChannelId, lb.logistics_supplier_id as logisticsSupplierId, lb.shop_name as shopName, lb.to_country as country, lb.order_time as orderTime, lbd.sign_time as signTime, lb.ship_time as shipTime, lb.remark, case when lb.ship_time is not null then FLOOR(EXTRACT(EPOCH FROM (now()-lb.ship_time))/3600) else FLOOR(EXTRACT(EPOCH FROM (now()-lb.order_time))/3600) end as actualHour from logistics_bill lb inner join logistics_bill_detail lbd on lbd.main_id = lb.id and lbd.is_deleted = false where ${params.sqlMap.default} and lb.order_type = #{params.orderType} and lb.is_deleted =false
${params.permissionSql}
order by lb.create_time desc ) SELECT tl.id, shopId, outstockId, transportNo, counterNo, carrierId, businessCode, outstockCode, tl.detailId, trackNo, logisticsStatus, logisticsTrack , invoicesStatus, shippingMethod, logisticsChannelId, logisticsSupplierId, shopName, country, orderTime, signTime, remark, actualHour, tc.estimatedFee, tc.actualFee from tms_logistics tl left join tms_cost tc on tl.id = tc.logistics_bill_id

SELECT lbd.track_status as tabFlag, count(1) as count FROM logistics_bill lb inner join logistics_bill_detail lbd on lb.id = lbd.main_id where lb.is_deleted = false and lbd.is_deleted = false and lb.order_type = #{orderType}
${permissionSql}
group by lbd.track_status

SELECT  EXTRACT(year FROM lb.order_time),  EXTRACT(month FROM lb.order_time) as month,
count(1)
FROM logistics_bill lb
inner join logistics_bill_detail lbd on lb.id = lbd.main_id
where lb.is_deleted = false and lbd.is_deleted = false
and lb.order_type = #{params.orderType}

    and  lbd.track_status in

        #{status}



    and lb.order_time >= #{params.beginOrderTime}


    and lb.order_time <=  #{params.endOrderTime}



    ${permissionSql}

group by EXTRACT(month FROM lb.order_time), EXTRACT(year FROM lb.order_time)
order by  EXTRACT(year FROM lb.order_time), EXTRACT(month FROM lb.order_time)

SELECT COUNT(CASE WHEN reconciliation_status = 'toBeGenerated' THEN 1 END) AS toBeCreate, COUNT(CASE WHEN reconciliation_status = 'toBeConfirm' THEN 1 END) AS toBeConfirm, COUNT(CASE WHEN reconciliation_status = 'confirmed' THEN 1 END) AS confirm, COUNT(CASE WHEN reconciliation_status = 'Reconciled' THEN 1 END) AS reconciliation FROM ( SELECT lbc.reconciliation_status FROM logistics_bill lb INNER JOIN logistics_bill_cost lbc ON lb.id = lbc.logistics_bill_id WHERE lb.is_deleted = false AND lbc.is_deleted = false and lb.order_type = #{orderType}
${permissionSql}
) AS subquery

SELECT lb.shop_id as shopId, lb.shop_name as shopName, lb.source_code as sourceCode, lb.source_id as relationId, lb.source_id as deliveryId, lb.source_code as businessCode, lb.id as sourceId, lb.transport_no as transportNo, lb.outstock_id as outstockId, lb.outstock_code as relationCode, lb.remark as remark, lbd.track_status as transportStatus, lbc.reconciliation_status as reconciliationStatus, lb.shipping_method as shippingMethod, lb.channel_id as logisticsChannelId, lb.logistics_supplier_id as logisticsSupplierId, lb.to_country as toCountry, lbc.logistics_bill_id as logisticBillId, lbc.actual_weight as actualWeight, lbc.volume_weight as volumeWeight, lbc.billing_weight as billingWeight, lbc.volume_weight_logistics as volumeWeightLogistics, lbc.weight_logistics as weightLogistics, lbc.weight_unit as actualWeightUnit, lbc.currency as currency, lbc.reconciliation_id as reconciliationId, lb.order_time as orderTime, lbd.track_no as trackNo, lbd.sign_time as receiveDate from logistics_bill lb inner join logistics_bill_cost lbc on lb.id = lbc.logistics_bill_id inner join logistics_bill_detail lbd on lbd.main_id = lb.id inner join logistics_channel lc on lc.id = lb.channel_id and lc.is_deleted = false
${params.sqlMap.default} and lb.is_deleted =false and lbc.is_deleted = false and lbd.is_deleted = false
and lb.order_type = #{orderType}
and lbc.reconciliation_status = #{reconciliationStatus}
and lbc.reconciliation_status = 'toBeGenerated'
and lbd.track_status = #{trackStatus}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
lb.id desc

SELECT lb.shop_id as shopId, lb.shop_name as shopName, lb.source_code as sourceCode, lb.source_id as relationId, lb.source_id as deliveryId, lb.id as sourceId, lb.outstock_code as relationCode, lb.transport_no as transportNo, lb.outstock_id as outstockId, lb.source_code as businessCode, lbd.track_status as transportStatus, lbc.reconciliation_status as reconciliationStatus, lb.shipping_method as shippingMethod, lb.channel_id as logisticsChannelId, lb.logistics_supplier_id as logisticsSupplierId, lb.to_country as toCountry, lbc.logistics_bill_id as logisticBillId, lbc.actual_weight as actualWeight, lbc.volume_weight as volumeWeight, lbc.billing_weight as billingWeight, lbc.volume_weight_logistics as volumeWeightLogistics, lbc.weight_logistics as weightLogistics, lbc.weight_unit as actualWeightUnit, lbc.weight_unit as volumeWeightUnit, lbc.weight_unit as billingWeightUnit, lbc.currency as currency, lbc.reconciliation_id as reconciliationId, lb.order_time as orderTime, lbd.track_no as trackNo, lbd.sign_time as receiveDate from logistics_bill lb left join logistics_bill_cost lbc on lb.id = lbc.logistics_bill_id AND lbc.is_deleted = FALSE left join logistics_bill_detail lbd on lbd.main_id = lb.id AND lbd.is_deleted = FALSE left join logistics_channel lc on lc.id = lb.channel_id and lc.is_deleted = false
and lb.is_deleted =false
and lb.order_type = #{orderType}
and lbc.reconciliation_status = #{reconciliationStatus}
and lbd.track_status = #{trackStatus}
and lb.id in
#{id}
and lb.transport_no in
#{trackNo}
and lbd.sign_time >= #{startDate} and (#{endDate}::TIMESTAMP + INTERVAL '1 DAY') > lbd.sign_time
and lb.logistics_supplier_id in
#{logisticsSupplierId}

select lb.id logisticsBillId, lb.outstock_id sourceId, lb.outstock_code sourceCode, lb.source_id businessId, lb.source_code businessCode, lb.transport_no transportNo, lb.logistics_supplier_id supplierId, lb.shop_id shopId, lb.shop_name shopName, lb.to_country toCountry, lb.channel_id channelId from logistics_bill lb left join logistics_bill_detail lbd on lb.id = lbd.main_id and lbd.is_deleted = false where lb.is_deleted = false and lb.order_type = 'firstMile' and lbd.track_status in ('ordered', 'Inspecting', 'trackIng', 'arrived', 'sign', 'exception')
and lb.id in
#{id}
